('coaching_templates','{"goal": ["شناخت وضعیت فعلی", "تعیین هدف", "ساخت عادت", "بررسی موانع", "مهارت", "تمرین", "ارزیابی", "اصلاح مسیر"], "study": ["ثبت وضعیت فعلی مطالعه", "هدف‌گذاری درسی", "ساخت عادت مطالعه‌ی روزانه", "بررسی موانع تمرکز", "یادگیری فعال و مرور", "تمرین آزمون", "ارزیابی پیشرفت", "اصلاح برنامه"], "career": ["شناخت علاقه و توانایی", "کاوش شغل‌ها", "انتخاب مهارت‌های لازم", "ساخت نقشه‌ی یادگیری", "شروع یادگیری مهارت", "پروژه‌ی عملی", "گفت‌وگو با متخصص", "بازنگری مسیر"], "path": ["شناخت خود", "انتخاب رشته", "انتخاب هدف", "ساخت مسیر", "برنامه‌ریزی", "اجرا", "مهارت و تجربه", "ورود به مرحله‌ی بعد"]}','قواعد','قالب برنامه‌ی کوچینگ ۸ هفته‌ای (JSON)',0),
