INSERT OR IGNORE INTO payment_settings (id,card_number,card_owner,bank_name,instructions,rules,min_amount,max_amount,receipt_required) VALUES
(1,'0000000000000000','نام صاحب کارت را از پنل مدیر وارد کنید','','مبلغ را کارت‌به‌کارت واریز کن، سپس شماره‌ی پیگیری را در همین صفحه ثبت کن. پس از بررسی، درخواست تو فعال می‌شود.','درخواست پس از تأیید پرداخت و هماهنگی زمان قطعی می‌شود. لغو پس از تأیید با هماهنگی پشتیبانی انجام می‌شود.',10000,100000000,0);
INSERT OR IGNORE INTO ai_settings (id,is_enabled,provider_name,base_url,model,system_prompt,temperature,max_tokens,daily_limit) VALUES
(1,0,'OpenAI-compatible','https://api.openai.com/v1','','تو «مشاور AI رایگان» پلتفرم «مسیر من» هستی. به زبان فارسی، ساده، محترمانه و کوتاه پاسخ بده. فقط راهنمایی بده و تصمیم نهایی را به کاربر و خانواده بسپار. تشخیص پزشکی یا روان‌شناختی نده. اگر اطلاعات کافی نداری صادقانه بگو و کاربر را به بخش‌های مرتبط سایت یا متخصص ارجاع بده. از داده‌های ساختاریافته‌ی پلتفرم که در ادامه می‌آید به‌عنوان منبع اصلی استفاده کن.',0.4,700,20);
INSERT OR IGNORE INTO tests (id,slug,title,description,kind,est_minutes,level,science_note,result_note,is_published,sort_order) VALUES
(1,'holland-interest','تست علاقه‌ی شغلی هالند (RIASEC)','کدام نوع فعالیت‌ها را دوست داری؟ بر اساس مدل شش‌بعدی هالند، الگوی علاقه‌ات مشخص می‌شود و رشته‌ها و شغل‌های هم‌راستا پیشنهاد می‌شود.','likert',10,'همه‌ی پایه‌ها','مبنای علمی: نظریه‌ی انتخاب شغل جان هالند (۱۹۵۹ و بعد) و ابزارهایی مثل O*NET Interest Profiler. سؤال‌ها در این پلتفرم اصیل نوشته شده‌اند و ابزار رسمی هنجاریابی‌شده نیستند؛ نتیجه را نقطه‌ی شروع گفت‌وگو و کاوش بدان، نه حکم نهایی.','نتیجه، علاقه‌ات را نشان می‌دهد نه توانایی‌ات. برای تصمیم بهتر آن را با تست توانایی، ارزش‌ها و گفت‌وگو با متخصص ترکیب کن.',1,1),
(2,'big-five-mini','تست شخصیت شغلی (پنج عامل بزرگ)','نسخه‌ی کوتاه مدل پنج‌عاملی شخصیت؛ برای شناخت سبک کار، تعامل و مدیریت استرس.','likert',6,'از ۱۴ سال به بالا','مبنای علمی: Mini-IPIP (Donnellan و همکاران، ۲۰۰۶) از بانک آیتم‌های عمومی IPIP که برای استفاده‌ی آزاد است. این تست غربالگری/تشخیص روان‌شناختی نیست. نمره‌ی بالا یا پایین «خوب یا بد» نیست و ترجیح را نشان می‌دهد.','شخصیت انتخاب‌های شغلی را محدود نمی‌کند؛ فقط نشان می‌دهد کدام محیط‌ها راحت‌تر یا نیازمند تمرین بیشترند.',1,2),
(3,'multiple-intelligences','تست هوش‌های چندگانه (گاردنر)','هشت حوزه‌ی توانمندی و علاقه‌ی خودت را ببین و بفهم از کدام مسیرها بیشتر لذت می‌بری.','likert',8,'همه‌ی پایه‌ها','مبنای علمی: نظریه‌ی هوش‌های چندگانه‌ی هاوارد گاردنر. توجه: این نظریه در روان‌سنجی به‌عنوان مدل «توانایی‌های سنجیده‌شده» تأیید نشده و بیشتر ابزاری برای خودشناسی و تنوع مسیرهاست؛ نتیجه‌ی تست را معیار قطعی توانایی ندان.','این تست ترجیح و تصور تو از خودت را می‌سنجد. برای سنجش توانایی واقعی از «تست استعداد و توانایی» و عملکرد تحصیلی هم کمک بگیر.',1,3),
(4,'learning-preference','تست ترجیح یادگیری (الهام‌گرفته از مدل VARK)','ببین بیشتر از کدام روش (دیداری، شنیداری، نوشتاری، عملی) لذت می‌بری تا روش مطالعه‌ات را متنوع‌تر کنی.','likert',5,'همه‌ی پایه‌ها','مبنای علمی: مدل VARK (فلمینگ). آیتم‌ها اصیل و نه پرسش‌نامه‌ی رسمی VARK هستند. مرور پژوهش‌ها (مثل Pashler و همکاران ۲۰۰۸) شواهد قوی برای اینکه «تطبیق آموزش با سبک یادگیری» نتیجه‌ی بهتری بدهد پیدا نکرده است؛ بنابراین نتیجه را برای تنوع روش‌ها استفاده کن، نه محدود شدن به یک روش.','بهترین روش‌ها برای همه‌ی سبک‌ها مشترک‌اند: خودآزمایی، مرور فاصله‌دار و تمرین متنوع. نتیجه‌ی تست فقط کمک می‌کند این روش‌ها را با ابزار مورد علاقه‌ات انجام بدهی.',1,4);
INSERT OR IGNORE INTO tests (id,slug,title,description,kind,est_minutes,level,science_note,result_note,is_published,sort_order) VALUES
(5,'aptitude-basic','تست توانایی و استعداد تحصیلی پایه','۱۲ سؤال کوتاه برای سنجش استدلال عددی، کلامی، منطقی و فضایی. هر سؤال یک پاسخ درست دارد.','ability',12,'از ۱۳ سال به بالا','مبنای علمی: قالب سؤال‌ها از آزمون‌های استاندارد استعداد (استدلال عددی/کلامی/انتزاعی/فضایی) الگو گرفته شده است. این نسخه‌ی کوتاه و آموزشی است و آزمون هنجاریابی‌شده نیست؛ برای تصمیم‌های مهم از آزمون رسمی و نظر متخصص کمک بگیر.','تعداد سؤال کم است؛ پس تفاوت‌های کوچک بین دسته‌ها را جدی نگیر. تمرین، توانایی‌ها را بهتر می‌کند.',1,5),
(6,'study-skills','تست مهارت‌های مطالعه و خودتنظیمی','کدام عادت‌های مطالعه‌ات قوی است و کدام نیاز به تقویت دارد؟','likert',7,'همه‌ی پایه‌ها','مبنای علمی: نظریه‌ی یادگیری خودتنظیم (Zimmerman) و مرور روش‌های مطالعه‌ی مؤثر (Dunlosky و همکاران ۲۰۱۳). سؤال‌ها اصیل نوشته شده‌اند و پرسش‌نامه‌ی رسمی نیستند.','دسته‌هایی که نمره‌ی پایین‌تری دارند بهترین فرصت رشد شما هستند؛ روی یکی دو مورد تمرکز کن نه همه.',1,6),
(7,'major-readiness','تست آمادگی انتخاب رشته و مسیر شغلی','چقدر برای تصمیم درباره‌ی رشته و شغل آماده‌ای؟ کدام بخش را باید تقویت کنی؟','likert',5,'دوره‌ی متوسطه','مبنای علمی: الهام‌گرفته از مفهوم «خودکارآمدی در تصمیم‌گیری شغلی» (Taylor و Betz) و مدل‌های آمادگی تصمیم‌گیری شغلی؛ آیتم‌ها اصیل هستند.','نمره‌ی پایین یعنی هنوز جای رشد داری، نه اینکه تصمیم اشتباه است. هر بخش یک اقدام مشخص دارد.',1,7),
(8,'work-values','تست ارزش‌های شغلی','در کار چه چیزی برایت مهم‌تر است: استقلال، درآمد، خدمت به دیگران، ثبات یا موفقیت؟','likert',5,'همه‌ی پایه‌ها','مبنای علمی: الهام‌گرفته از ارزش‌های کاری در سامانه‌ی O*NET (پیشرفت، استقلال، شناخته‌شدن، روابط، حمایت، شرایط کار). آیتم‌ها اصیل هستند.','ارزش‌ها به تو کمک می‌کنند بین دو شغل با علاقه‌ی مشابه تصمیم بگیری.',1,8);
INSERT OR IGNORE INTO test_categories (id,test_id,code,title,description,suggested_majors,suggested_jobs,suggested_skills,next_action,sort_order) VALUES
(1,1,'R','واقع‌گرا (عملی)','علاقه به کار عملی، ابزار، دستگاه‌ها و فعالیت‌های فنی و بیرون از میز. این افراد معمولاً از ساختن، تعمیر کردن و دیدن نتیجه‌ی ملموس کار لذت می‌برند.','electrical-engineering,mechanical-engineering,civil-engineering,mining-engineering,surveying-engineering,naval-engineering,textile-engineering,water-engineering,geology,operating-room-technology,radiology-technology,environmental-health,occupational-health,emergency-medical-services','electrical-engineer,mechanical-engineer,civil-engineer,network-administrator,it-support-specialist,network-technician,mining-engineer,surveyor,naval-engineer,textile-engineer,water-resources-engineer,hse-officer,geologist,lab-technician','problem-solving,mathematical-thinking','رشته‌های فنی‌مهندسی را بررسی کن و اگر امکانش هست یک کارگاه یا پروژه‌ی عملی کوچک انجام بده.',1),
(2,1,'I','پژوهشی (تحلیلی)','علاقه به فکر کردن، تحلیل، کشف علت‌ها و حل مسئله. این افراد به علم، ریاضی، داده و پژوهش گرایش دارند.','computer-engineering,medicine,biology,industrial-engineering,chemical-engineering,materials-engineering,aerospace-engineering,petroleum-engineering,environmental-engineering,biomedical-engineering,energy-engineering,nuclear-engineering,polymer-engineering,mechatronics-engineering','researcher,data-analyst,physician,software-developer,web-developer,mobile-app-developer,data-scientist,machine-learning-engineer,cybersecurity-analyst,database-administrator,devops-engineer,game-developer,embedded-systems-engineer,system-analyst','critical-thinking,data-analysis,mathematical-thinking','یک مسئله‌ی واقعی یا پروژه‌ی پژوهشی کوچک انتخاب کن و مراحل بررسی آن را بنویس.',2),
(3,1,'A','هنری (خلاق)','علاقه به خلق ایده، زیبایی‌شناسی، بیان آزاد و کارهای غیرتکراری در هنر، طراحی، نوشتن و رسانه.','architecture,graphic-design,social-communication,journalism,persian-literature,arabic-literature,english-translation,english-literature,german-language,french-language,russian-language,spanish-language,italian-language,turkish-language','architect,graphic-designer,ux-ui-designer,interior-designer,landscape-architect,industrial-designer,journalist,content-writer,writer,translator,interpreter,painter,sculptor,illustrator','creativity,digital-literacy','نمونه‌کار (پرتفولیو) بساز؛ حتی سه کار کوچک برای شروع کافی است.',3),
(4,1,'S','اجتماعی (یاری‌گر)','علاقه به کمک، آموزش، همدلی و کار با انسان‌ها. این افراد از اثرگذاری مستقیم بر زندگی دیگران انرژی می‌گیرند.','psychology,education,medicine,nursing,midwifery,physiotherapy,occupational-therapy,speech-therapy,public-health,social-work,educational-sciences,counseling,special-education,early-childhood-education,elementary-education','psychologist,teacher,physician,nurse,midwife,physiotherapist,occupational-therapist,speech-therapist,public-health-specialist,health-educator,sports-coach,fitness-trainer,physical-education-teacher,hr-specialist,tour-guide','empathy,communication','با یک نفر از حوزه‌های آموزش یا مشاوره گفت‌وگو کن و یک تجربه‌ی داوطلبانه را امتحان کن.',4),
(5,1,'E','متهور (کارآفرین)','علاقه به رهبری، اقناع، ریسک حساب‌شده، فروش و ساختن کسب‌وکار یا مدیریت پروژه.','management,law,sports-management,financial-management,industrial-management,marketing-management,public-administration,international-relations,tourism-management','business-manager,lawyer,product-manager,project-manager,sports-manager,marketing-manager,digital-marketer,sales-manager,entrepreneur,commercial-affairs-expert,tourism-manager,diplomat,public-relations-specialist,legal-consultant','leadership,communication','یک پروژه‌ی کوچک (رویداد، فروش، باشگاه) را رهبری کن و نتیجه را ثبت کن.',5),
(6,1,'C','قراردادی (سازمان‌ده)','علاقه به نظم، دقت، ساختار مشخص، کار با داده و اسناد و اجرای دقیق برنامه.','management,computer-engineering,health-information-management,accounting,library-information-science,accounting-associate','data-analyst,business-manager,qa-engineer,quality-control-engineer,medical-records-specialist,accountant,auditor,tax-expert,banking-specialist,supply-chain-specialist,public-administrator,librarian,editor-proofreader,bookkeeper,payroll-specialist,procurement-officer','time-management,data-analysis','مهارت کار با صفحه‌گسترده (اکسل) را تمرین کن و یک برنامه‌ی بودجه یا زمان‌بندی بساز.',6),
(7,2,'E','برون‌گرایی','انرژی گرفتن از تعامل اجتماعی، فعال‌بودن و صحبت کردن در جمع. نمره‌ی بالا یعنی راحتی بیشتر در موقعیت‌های اجتماعی؛ نمره‌ی پایین یعنی ترجیح تعامل کم‌تر و عمیق‌تر (هر دو سالم‌اند).','management,law,education,marketing-management,political-science,sports-management','business-manager,lawyer,teacher,marketing-manager,sales-manager,diplomat,entrepreneur','leadership,communication','اگر نمره‌ات بالاست نقش‌های ارتباطی و رهبری را امتحان کن؛ اگر پایین است کارهای تمرکزی و عمیق (پژوهش، طراحی، برنامه‌نویسی) می‌تواند مناسب باشد.',1),
(8,2,'A','توافق‌پذیری (همدلی)','تمایل به همدلی، همکاری و توجه به دیگران.','psychology,education,medicine,counseling,social-work,nursing,occupational-therapy','psychologist,teacher,physician,counselor,social-worker,nurse,occupational-therapist','empathy,teamwork','نقش‌های گروهی و خدمات انسانی را بررسی کن و مهارت گوش‌دادن فعال را تمرین کن.',2),
(9,2,'C','وظیفه‌شناسی (نظم)','نظم، برنامه‌ریزی، پشتکار و دقت. یکی از بهترین پیش‌بینی‌کننده‌های عملکرد تحصیلی و شغلی در پژوهش‌هاست.','management,civil-engineering,medicine,accounting,industrial-engineering,pharmacy','business-manager,civil-engineer,physician,accountant,auditor,pharmacist,quality-control-engineer','time-management','برنامه‌ی مطالعه‌ی هفتگی بساز و پیشرفتت را ثبت کن.',3),
(10,2,'S','ثبات هیجانی','توانایی حفظ آرامش در فشار. نمره‌ی پایین به معنای بیماری نیست؛ فقط نشان می‌دهد مدیریت استرس نیاز به تمرین دارد.','medicine,law','physician,lawyer','time-management,empathy','تمرین‌های مدیریت استرس، خواب کافی و ورزش منظم را وارد برنامه کن؛ در صورت فشار زیاد با مشاور صحبت کن.',4);
