(21,4,'A','شنیداری','ترجیح یادگیری با شنیدن، گفت‌وگو و توضیح شفاهی.','','','communication','مطالب را برای خودت یا دوستت بلند توضیح بده و از گفت‌وگوی درسی استفاده کن.',2),
(22,4,'R','خواندن/نوشتن','ترجیح یادگیری با متن، یادداشت‌برداری و فهرست.','','','time-management','خلاصه‌نویسی با کلمات خودت و نوشتن سؤال از متن را انجام بده.',3),
(23,4,'K','حرکتی/عملی','ترجیح یادگیری با تمرین، مثال واقعی و انجام دادن.','','','problem-solving','حل تمرین، آزمایش و مثال کاربردی را زیاد کن و مطالعه را با حرکت ترکیب کن.',4),
(24,5,'NUM','توانایی عددی','دقت و سرعت در استدلال با اعداد و نسبت‌ها.','computer-engineering,electrical-engineering,management,statistics,accounting,actuarial-science,mathematics','data-analyst,electrical-engineer,business-manager,statistician,accountant,actuary,financial-analyst','mathematical-thinking,data-analysis','تمرین منظم مسائل کلامی ریاضی و آمار را در برنامه بگذار.',1),
(25,5,'VER','توانایی کلامی','درک روابط بین واژه‌ها و استدلال زبانی.','law,education,psychology,persian-literature,journalism,english-translation,political-science','lawyer,teacher,psychologist,writer,journalist,translator,content-writer','communication,english','مطالعه‌ی متن‌های متنوع و ساختن واژگان را تقویت کن.',2),
(26,5,'LOG','استدلال منطقی','نتیجه‌گیری درست از مقدمات و تشخیص الگو.','computer-engineering,law,medicine,computer-science,mathematics,artificial-intelligence,philosophy','software-developer,lawyer,physician,data-scientist,machine-learning-engineer,mathematician,cybersecurity-analyst','critical-thinking,problem-solving','معماهای منطقی و مسائل استدلالی را تمرین کن.',3),
(27,5,'SPA','توانایی فضایی','تصور ذهنی اشیا، جهت‌ها و تغییر وضعیت آن‌ها.','architecture,mechanical-engineering,civil-engineering,industrial-design,surveying-engineering,interior-architecture,urban-planning','architect,mechanical-engineer,civil-engineer,industrial-designer,surveyor,interior-designer,urban-planner','creativity,problem-solving','تمرین‌های هندسه‌ی فضایی و نقشه‌خوانی را انجام بده.',4),
(28,6,'PLAN','برنامه‌ریزی و هدف‌گذاری','توانایی تعیین هدف، تنظیم برنامه و اصلاح آن. طبق نظریه‌ی یادگیری خودتنظیم، برنامه‌ریزی و پایش از مؤثرترین عادت‌های یادگیری است.','','','time-management','برنامه‌ی هفتگی بنویس، برای هر درس هدف قابل‌اندازه‌گیری بگذار و آخر هفته با برنامه مقایسه کن.',1),
(29,6,'FOCUS','تمرکز و محیط','حفظ تمرکز و کنترل عوامل حواس‌پرتی.','','','time-management','مطالعه‌ی بلوک‌های ۲۵ تا ۵۰ دقیقه‌ای با استراحت کوتاه و دور کردن گوشی را امتحان کن.',2),
(30,6,'ACTIVE','یادگیری فعال','استفاده از روش‌های مؤثر مثل خودآزمایی (بازیابی فعال) و مرور فاصله‌دار. این روش‌ها در پژوهش‌های یادگیری از خواندن مکرر یا خط‌کشیدن مؤثرترند.','','','critical-thinking','پس از هر مبحث کتاب را ببند و آنچه یادت مانده را بنویس؛ مرور را با فاصله (۱، ۳، ۷ روز) انجام بده.',3);
