INSERT OR IGNORE INTO majors (id,slug,name,description,suitable_for,key_lessons,abilities,skills,universities,study_path,related_jobs,job_market,future_skills,pros,challenges,faq,similar_majors,holland_codes,konkur_group,is_published,sort_order) VALUES
(1,'computer-engineering','مهندسی کامپیوتر','طراحی و ساخت نرم‌افزار، سیستم‌های هوشمند، شبکه و داده. پایه‌ی آن ریاضیات گسسته، الگوریتم و برنامه‌نویسی است.','کسانی که به حل مسئله، منطق و ساختن ابزار دیجیتال علاقه دارند.','ریاضی، فیزیک، منطق و برنامه‌نویسی','استدلال منطقی، صبر برای اشکال‌یابی، یادگیری مداوم','برنامه‌نویسی، ساختار داده، تحلیل مسئله، کار تیمی','دانشگاه‌های دولتی، آزاد و غیرانتفاعی متعدد؛ ظرفیت و سطح آن‌ها را از منابع رسمی سنجش بررسی کن.','کارشناسی ۴ ساله، ارشد ۲ ساله، دکتری؛ امکان ورود به بازار کار با پروژه و کارآموزی از میانه‌ی دوره.','software-developer,data-analyst,web-developer,mobile-app-developer,machine-learning-engineer,cybersecurity-analyst,network-administrator,database-administrator,devops-engineer,ux-ui-designer,qa-engineer,game-developer,product-manager,system-analyst','تقاضا در حوزه‌های نرم‌افزار، داده و هوش مصنوعی بالا است اما رقابت برای موقعیت‌های خوب نیز جدی است؛ نمونه‌کار و مهارت واقعی تعیین‌کننده است.','هوش مصنوعی، امنیت سایبری، داده، رایانش ابری','بازار کار گسترده، امکان کار دورکاری، رشد مهارتی سریع','به‌روز ماندن دائمی، رقابت، کار طولانی پشت صفحه','آیا حتماً باید ریاضی قوی باشم؟ پایه‌ی منطقی و ریاضی لازم است اما با تمرین قابل تقویت است.
آیا بدون دانشگاه هم می‌شود برنامه‌نویس شد؟ بله ولی مدرک و شبکه‌ی ارتباطی در بسیاری از فرصت‌ها کمک می‌کند.','electrical-engineering,management','I,C','ریاضی',1,1),
(2,'medicine','پزشکی','پیشگیری، تشخیص و درمان بیماری‌ها. مسیر طولانی با آموزش نظری و بالینی.','کسانی که به علوم زیستی، خدمت به انسان و تحمل فشار و مسئولیت علاقه دارند.','زیست‌شناسی، شیمی، فیزیک','حافظه‌ی قوی، دقت، تحمل فشار، همدلی','مهارت ارتباط با بیمار، تصمیم‌گیری بالینی، مطالعه‌ی مستمر','دانشکده‌های علوم پزشکی کشور؛ ظرفیت محدود و رقابت بسیار بالا.','دوره‌ی عمومی چندساله، سپس تخصص یا اشتغال؛ مسیر طولانی و پرفشار.','physician,researcher','نیاز جامعه به پزشک ثابت است اما توزیع فرصت‌ها و شرایط کاری بر اساس شهر و تخصص فرق دارد.','پزشکی دیجیتال، ژنومیکس، تحلیل داده‌ی سلامت','احترام اجتماعی، اثر مستقیم بر زندگی مردم','مسیر طولانی، ساعت کاری سنگین، فشار روانی','آیا پزشکی فقط حفظیات است؟ حفظ زیاد لازم است ولی استدلال بالینی و ارتباط هم بسیار مهم است.','biology,psychology','I,S','تجربی',1,2),
(3,'electrical-engineering','مهندسی برق','طراحی و بهره‌برداری از سیستم‌های الکتریکی، الکترونیک، مخابرات و کنترل.','کسانی که به فیزیک، ریاضی و ساخت یا تحلیل مدار و سیستم علاقه دارند.','ریاضی، فیزیک','تحلیل ریاضی، تفکر سیستمی، دقت','مدارها، سیگنال، کنترل، برنامه‌نویسی','دانشگاه‌های فنی کشور در سطوح مختلف.','کارشناسی ۴ ساله و گرایش‌های قدرت، الکترونیک، مخابرات، کنترل.','electrical-engineer,embedded-systems-engineer,biomedical-engineer,telecom-engineer,automation-engineer,electrician','نیاز به متخصصان برق در صنعت و انرژی وجود دارد؛ بازار کار به گرایش و مهارت بستگی دارد.','انرژی‌های تجدیدپذیر، اینترنت اشیا، سیستم‌های نهفته','دامنه‌ی صنعتی گسترده، پایه‌ی ریاضی قوی','دروس سنگین، نیاز به مهارت عملی کنار نظری','برق و کامپیوتر چه فرقی دارند؟ برق به سخت‌افزار و سیستم‌های فیزیکی نزدیک‌تر است.','computer-engineering,mechanical-engineering','R,I','ریاضی',1,3),
(4,'mechanical-engineering','مهندسی مکانیک','طراحی، ساخت و تحلیل ماشین‌ها و سیستم‌های مکانیکی و حرارتی.','کسانی که به ماشین، طراحی قطعه و فیزیک کاربردی علاقه دارند.','ریاضی، فیزیک','تصور فضایی، تحلیل فیزیکی، خلاقیت فنی','طراحی به کمک رایانه، مکانیک سیالات، ترمودینامیک','دانشگاه‌های فنی کشور.','کارشناسی ۴ ساله؛ گرایش‌های جامدات، حرارت و سیالات، ساخت و تولید.','mechanical-engineer,aerospace-engineer,energy-engineer,naval-engineer,industrial-designer,auto-mechanic,cnc-operator','صنایع تولیدی و انرژی جذب‌کننده‌ی مهندس مکانیک هستند؛ مهارت نرم‌افزاری و عملی مهم است.','ساخت افزودنی، رباتیک، انرژی','تنوع صنعتی زیاد','بخشی از کارها در محیط صنعتی و سخت است','مکانیک برای دختران مناسب است؟ بله؛ توانایی و علاقه مهم‌تر از جنسیت است.','electrical-engineering,civil-engineering','R,I','ریاضی',1,4);
INSERT OR IGNORE INTO majors (id,slug,name,description,suitable_for,key_lessons,abilities,skills,universities,study_path,related_jobs,job_market,future_skills,pros,challenges,faq,similar_majors,holland_codes,konkur_group,is_published,sort_order) VALUES
(5,'civil-engineering','مهندسی عمران','طراحی، محاسبه و اجرای ساختمان، پل، راه، سازه‌های آبی و زیرساخت.','کسانی که به ساخت و ساز و حل مسئله‌ی واقعی علاقه دارند.','ریاضی، فیزیک','تصور فضایی، دقت، مسئولیت‌پذیری','تحلیل سازه، نقشه‌خوانی، مدیریت پروژه','دانشگاه‌های فنی کشور.','کارشناسی ۴ ساله؛ گرایش سازه، ژئوتکنیک، آب، حمل‌ونقل، مدیریت ساخت.','civil-engineer,surveyor,water-resources-engineer','بازار به وضعیت ساخت‌وساز و پروژه‌های عمرانی وابسته است و نوسان دارد.','ساخت هوشمند، ساختمان سبز، مدل‌سازی اطلاعات ساختمان','کار میدانی و اثر مشهود','وابستگی به بازار ساخت‌وساز، گاهی کار در سایت','آیا کار سایت اجباری است؟ بسته به گرایش شغلی متفاوت است.','architecture,mechanical-engineering','R,E','ریاضی',1,5),
(6,'architecture','معماری','طراحی فضاها و ساختمان‌ها با تلفیق هنر، فناوری و نیاز انسان.','کسانی که به طراحی، خلاقیت و فضاسازی علاقه دارند.','ریاضی، طراحی، فیزیک','خلاقیت، تصور فضایی، مهارت ارائه','طراحی، مدل‌سازی سه‌بعدی، ارائه‌ی ایده','دانشگاه‌ها و دانشکده‌های هنر و معماری.','کارشناسی ۴ تا ۵ ساله؛ گرایش‌ها و کار در دفاتر طراحی.','architect,graphic-designer,urban-planner,interior-designer,landscape-architect','بازار معماری به شبکه‌ی ارتباطی و پرتفولیو بستگی دارد و رقابتی است.','طراحی پایدار، مدل‌سازی اطلاعات ساختمان','خلاقیت و ماندگاری اثر','کار زیاد و فشار زمانی پروژه','آیا نقاشی قوی لازم است؟ مهارت طراحی مفید است ولی با تمرین رشد می‌کند.','civil-engineering,graphic-design','A,R','هنر/ریاضی',1,6),
(7,'psychology','روان‌شناسی','مطالعه‌ی علمی رفتار و فرایندهای ذهنی و کاربرد آن در سلامت، آموزش و سازمان.','کسانی که به انسان‌شناسی، همدلی و پژوهش رفتار علاقه دارند.','زیست‌شناسی، آمار، ادبیات','همدلی، تحلیل، اخلاق حرفه‌ای','گوش دادن فعال، آمار و روش تحقیق','دانشکده‌های علوم انسانی و روان‌شناسی.','کارشناسی و معمولاً ادامه‌ی تحصیلات تکمیلی و گواهی‌های تخصصی برای فعالیت بالینی.','psychologist,teacher,researcher,hr-specialist,counselor,education-researcher','فرصت‌ها در مشاوره، آموزش و سازمان است؛ فعالیت بالینی نیازمند مجوز و تحصیلات تکمیلی است.','سلامت روان دیجیتال، روان‌شناسی داده','اثرگذاری انسانی، تنوع مسیرها','نیاز به تحصیلات تکمیلی برای تخصص','روان‌شناسی یعنی فقط مشاوره؟ خیر؛ پژوهش، سازمان، ورزش، تربیتی و... هم دارد.','education,medicine','S,I','انسانی/تجربی',1,7),
(8,'law','حقوق','مطالعه‌ی قوانین و نظام‌های حقوقی و کاربرد آن در وکالت، قضاوت و مشاوره.','کسانی که به استدلال، بحث و عدالت علاقه دارند.','ادبیات، منطق، عربی','استدلال، مهارت کلامی و نوشتاری، دقت','نگارش حقوقی، استدلال، مذاکره','دانشکده‌های حقوق و علوم سیاسی.','کارشناسی، ورود به وکالت یا قضاوت با شرایط و آزمون‌های قانونی.','lawyer,tax-expert,legal-consultant,judge,compliance-officer','بازار وکالت رقابتی است و شبکه‌ی ارتباطی و تخصص نقش مهمی دارد.','حقوق فناوری و داده، حقوق بین‌الملل','اعتبار حرفه‌ای، مهارت‌های ارتباطی','حجم مطالعه‌ی زیاد، رقابت وکالت','آیا حقوق فقط حفظی است؟ درک و استدلال بسیار مهم است.','management,psychology','E,C','انسانی',1,8);
INSERT OR IGNORE INTO majors (id,slug,name,description,suitable_for,key_lessons,abilities,skills,universities,study_path,related_jobs,job_market,future_skills,pros,challenges,faq,similar_majors,holland_codes,konkur_group,is_published,sort_order) VALUES
(9,'management','مدیریت و کسب‌وکار','برنامه‌ریزی، سازمان‌دهی، بازاریابی، مالی و رهبری کسب‌وکار.','کسانی که به رهبری، کارآفرینی و تصمیم‌گیری علاقه دارند.','ریاضی، اقتصاد','ارتباط، تحلیل، رهبری','مدیریت پروژه، تحلیل مالی، مذاکره','دانشکده‌های مدیریت و اقتصاد.','کارشناسی و ارشد گرایش‌های مالی، بازاریابی، منابع انسانی و کارآفرینی.','business-manager,data-analyst,product-manager,sports-manager,sales-manager,hr-specialist,entrepreneur,insurance-consultant,brand-manager,business-consultant,operations-manager,ecommerce-manager,retail-manager,hotel-manager,school-principal,startup-product-owner,payroll-specialist,procurement-officer,office-administrator','بازار به تجربه و مهارت عملی حساس است؛ کارآفرینی فرصت و ریسک دارد.','تحلیل داده‌ی کسب‌وکار، بازاریابی دیجیتال','تنوع مسیر، امکان کارآفرینی','رقابت و نیاز به تجربه‌ی عملی','آیا مدیریت یعنی رئیس شدن؟ مدیریت مجموعه‌ای از مهارت‌های تحلیل و سازمان‌دهی است.','law,computer-engineering','E,C','انسانی/ریاضی',1,9),
(10,'graphic-design','طراحی گرافیک و ارتباط تصویری','طراحی پیام‌های تصویری برای برند، رسانه، وب و چاپ.','کسانی که خلاق‌اند و به تصویر و ایده علاقه دارند.','هنر، طراحی، رایانه','خلاقیت، ذوق بصری، مهارت نرم‌افزار','طراحی، ترکیب‌بندی، نرم‌افزارهای طراحی','دانشکده‌های هنر.','کارشناسی و پرتفولیو؛ امکان فریلنس.','graphic-designer,ux-ui-designer,illustrator,animator,digital-media-designer','بازار به کیفیت نمونه‌کار و بازاریابی شخصی وابسته است و رقابتی است.','طراحی تجربه‌ی کاربری، حرکت‌نگاری','خلاقیت و انعطاف کاری','نوسان درآمد در فریلنس','آیا بدون دانشگاه می‌شود طراح شد؟ بله، ولی پرتفولیو حیاتی است.','architecture,computer-engineering','A,E','هنر',1,10),
(11,'education','علوم تربیتی و آموزش','مطالعه‌ی یادگیری و روش‌های آموزش و تربیت.','کسانی که به تدریس، پرورش انسان و ارتباط علاقه دارند.','ادبیات، روان‌شناسی، آمار','صبر، ارتباط، خلاقیت آموزشی','تدریس، طراحی آموزش، ارزشیابی','دانشگاه‌های تربیت‌معلم و علوم تربیتی.','کارشناسی و ورود به آموزش با شرایط استخدامی رسمی یا غیردولتی.','teacher,school-principal','بازار به شرایط استخدام و آموزشی و شهر وابسته است.','آموزش دیجیتال، طراحی محتوای آموزشی','معنا و اثر اجتماعی','درآمد و شرایط کاری نامطمئن در برخی مسیرها','معلمی فقط در مدرسه است؟ خیر؛ آموزش آنلاین و مراکز آموزشی هم هست.','psychology,management','S,A','انسانی',1,11),
